"""Build one batch of reviewed authoring specifications, leaving acceptance pending."""
from pathlib import Path
import json,runpy,sys
R=Path(__file__).resolve().parents[1]
a=runpy.run_path(str(R/'tools/cisco-dc-authoring.py')); specs=a['S']; sources=a['SRC']
m=json.loads((R/'content/enrichment.json').read_text(encoding='utf-8')); inv=json.loads((R/'content/roadmap-inventory.json').read_text(encoding='utf-8'))
batch=sys.argv[1]; assert batch in ('17','18')
bm=next(b for b in m['batches'] if b['id']==batch)
if batch=='18': assert next(b for b in m['batches'] if b['id']=='17')['status']=='completed','Accept Batch 17 first.'
names={n['id']:n['name'] for n in inv['nodes']}; order=list(names)
S=[s for s in specs if s['id'] in bm['nodeIds']]; assert {s['id'] for s in S}==set(bm['nodeIds'])
scope={
 'evidence':'This is a guided evidence review. The three incident stages are authored scenarios, not captured device output. Choosing a stage does not run a command, discover hardware or change any network.',
 'vpc':'Steady-state two-peer teaching relation with both devices assumed powered and configuration consistent. It distinguishes peer-link and keepalive loss; dual loss is deliberately indeterminate. Timers, boot sequence, auto-recovery, peer-switch, per-VLAN consistency and orphan policy are not simulated.',
 'vni':'Compare two supplied local VLAN-to-L2-VNI mappings. Different VLAN numbers can map to the same VNI. Matching VNI numbers establish identifier consistency only; routing, EVPN policy, platform reserved values and device scale remain outside this arithmetic worksheet.',
 'vxlan':'Outer IP byte budget = inner IP + inner Ethernet 14 + optional inner tag 4 + VXLAN 8 + UDP 8 + base outer IP 20 or 40. No FCS, outer Ethernet, IP options/extensions, encryption or measured path MTU. A retained inner tag is an explicit arithmetic input, not a claim of default platform behavior.',
 'evpn':'Single synthetic type-2 route eligibility: BGP session, EVPN family, route presence, exact RT membership and reachable next hop. RD is deliberately not an import gate. No full BGP selection, hardware programming, MAC mobility, multihoming or measured forwarding.',
 'fabric':'Symmetric per-leaf uplink envelope: remaining links times rate, compared to supplied inter-leaf demand. Two spines and four leaves are the reference topology. No per-flow hashing, queues, convergence or actual traffic.',
 'aci':'Narrow inter-EPG policy relation within one enforced VRF, with no preferred groups, vzAny, unenforced mode, intra-EPG exceptions or service graphs. Attachment, route, deployed policy, matching consumer/provider contract and destination port must all agree. APIC availability is shown separately and does not erase existing policy in this bounded exercise.'}
lessons=[];work=['# Cisco Data Center — Batch '+batch+' evidence workbook','','Version scopes: NX-OS 10.5(x), ACI 6.0(x), and explicitly historical family/FabricPath references. Exact model/release support remains a target prerequisite. All Cisco commands below are guided and unexecuted. Browser models and offline artifacts do not certify hardware, convergence, storage access or production operation.','']
for s in S:
 id=s['id'];title=names[id];ts=s['terms'];ms=s['mechanism'];kind='vni' if id=='s7-g3-t1' else s['kind'];qs=list(s['questions'])
 qs += [
  (f'In the {title} incident, what is the failing evidence boundary?',s['fault'],'Compare the stated observation with the mechanism, then separate a demonstrated fault from an unsupported inference.'),
  (f'What exact recovery evidence is required for this {title} incident?',s['restore'],'A repaired configuration or status flag is narrower than restoration of the original intended operation.'),
  (f'Explain the difference between {ts[0][0]} and {ts[1][0]} in this lesson.',ts[0][1]+'. '+ts[1][1]+'.',ts[0][2]+' '+ts[1][2]),
  (f'Which conclusion about {title} would exceed the exercise evidence?',scope[kind],'The exercise evaluates only its declared inputs. Actual target behavior requires a supported environment and retained observations.')]
 exams=[dict(questionId=f'{id}-Q{i+1}',topicId=id,difficulty='foundational' if i<2 else 'intermediate' if i<5 else 'advanced',type='short-answer',question=q[0],answer=q[1],explanation=q[2],testedConcept=(ts[i%3][0] if i<6 else ['Incident diagnosis','Exact restoration','Terminology boundary','Evidence scope'][i-6])) for i,q in enumerate(qs)]
 # All written questions use explicit self-assessment; there is no fabricated automatic grading.
 quick=[dict(questionId=f'{id}-QC{i+1}',topicId=id,difficulty='intermediate',type='short-answer',question=q[0],answer=q[1],explanation=q[2],testedConcept=q[3]) for i,q in enumerate([
  ('Name the first observation you would retain before this exercise.',s['operation'],'Bind evidence to an observer, target and time rather than relying on an unlabeled screenshot.','Baseline'),
  ('Trace the second mechanism boundary in your own words.',ms[1],ts[1][2],'Mechanism'),
  ('Which term in this lesson is easiest to overinterpret, and what is its limit?',ts[2][0]+': '+ts[2][1]+'. '+ts[2][2],'Use the stated limitation to prevent a stronger claim than the evidence supports.','Scope')])]
 prerequisites={
 's7-g0-t0':['s6-g3-t0'],'s7-g0-t1':['s7-g0-t0'],'s7-g0-t2':['s7-g0-t1'],'s7-g0-t3':['s7-g0-t0'],
 's7-g0-t4':['s7-g0-t3'],'s7-g0-t5':['s7-g0-t3'],'s7-g0-t6':['s7-g0-t3'],'s7-g0-t7':['s7-g0-t1','s7-g0-t3'],
 's7-g1-t0':['s7-g0-t2','s1-g3-t3'],'s7-g1-t1':['s7-g1-t0'],'s7-g1-t2':['s7-g1-t0'],'s7-g1-t3':['s7-g1-t1','s7-g1-t2'],
 's7-g2-t0':['s7-g0-t6','s1-g3-t3'],'s7-g2-t1':['s7-g0-t3'],'s7-g2-t2':['s7-g2-t1'],'s7-g2-t3':['s6-g3-t2','s1-g4-t0'],
 's7-g3-t0':['s1-g3-t0','s1-g4-t0'],'s7-g3-t1':['s7-g3-t0'],'s7-g3-t2':['s7-g3-t1'],
 's7-g4-t0':['s7-g3-t2'],'s7-g4-t1':['s7-g4-t0'],'s7-g4-t2':['s6-g3-t2','s7-g4-t1'],
 's7-g5-t0':['s7-g4-t2'],'s7-g5-t1':['s7-g5-t0'],'s7-g5-t2':['s7-g5-t0'],'s7-g5-t3':['s7-g5-t0'],
 's7-g5-t4':['s7-g5-t3'],'s7-g5-t5':['s7-g5-t4'],'s7-g5-t6':['s7-g5-t4','s7-g5-t5'],'s7-g5-t7':['s7-g5-t4','s7-g5-t6'],
 's7-g5-t8':['s7-g5-t5','s7-g5-t7'],'lab-7':['s7-g1-t3','s7-g4-t2','s7-g5-t8']}
 prereq=prerequisites[id]
 steps=[s['operation'],'Create an evidence table with target identity, release/mode, observer, time, expected result and actual result. Use the documented topology and distinguish configuration intent from operational evidence.',
  'Use the baseline, fault and recovery buttons in the workbench. Predict the consequence before revealing the analyst note. Record which observation would disprove your diagnosis.',
  s['fault'],s['restore'],
  'If a supported disposable Cisco target is available, collect the listed read-only commands first. Any configuration exercise requires the exact release guide, an owned baseline, a reviewed diff and an independently tested recovery session. This course does not execute those target changes.',
  'Retest the original permitted operation and an explicitly prohibited operation after restoration. Keep service outcomes separate from routing, interface and controller status. Archive sanitized before/fault/after evidence and the exact scope of what was not tested.']
 security='Preserve the tenant and management boundaries while investigating. '+ts[2][2]+' Restrict administrative access and exports; redact endpoint identities and credentials. A shortcut that restores connectivity by admitting every VLAN, route target or contract can create a larger isolation failure. Keep a negative test for the intentionally excluded tenant or service.'
 performance='Evaluate the workload at the relevant boundary: '+ts[1][0]+'. '+ms[1]+' Record rates, packet sizes and the named failure condition before comparing capacity. Healthy port sums, control sessions and controller health do not establish application throughput, loss or tail latency. The workbench scope is explicit: '+scope[kind]
 l=dict(id=id,batch=batch,title=title,subtitle=s['operation'],level='Intermediate → Advanced',minutes=110 if id=='lab-7' else 55,interactive='cdc-'+id,
 definition=s['definition'],purpose=s['operation'],mental='Think of the service as a sequence of independently verifiable boundaries. '+ms[0]+' The handoff to '+ts[1][0]+' is where a successful first observation can still lead to a failed transaction. '+ts[2][2]+' This model is useful for selecting the next observation, not for predicting undocumented vendor behavior. '+scope[kind],
 components=[t[0]+': '+t[1]+'. '+t[2] for t in ts],mechanism=ms,
 flow=[['Service boundary',s['definition']],[ts[0][0],ms[0]],[ts[1][0],ms[1]],[ts[2][0],ms[2]]],comparison=ts,
 example='Baseline task: '+s['operation']+' Incident: '+s['fault']+' Recovery requirement: '+s['restore']+' Worked reasoning: '+qs[0][0]+' '+qs[0][1]+' '+qs[0][2]+' Alternative check: '+qs[3][0]+' '+qs[3][1]+' '+qs[3][2],
 ports='NX-OS SSH commonly uses TCP 22 and APIC HTTPS TCP 443. BGP session transport uses TCP 179; VXLAN uses assigned UDP destination 4789. These are distinct paths. FabricPath, vPC port channels, FEX host links and VNI identifiers do not acquire an application TCP port merely from their names. Permit only the actual supported management/control/data paths required by the design.',
 commands=[dict(filename='guided-cisco-observation.txt',platform='Guided Cisco observation; exact source scope applies; not executed on a target',code=s['command'],explanation='Collect these only on the intended supported device, with read-only privilege. '+s['operation'],expected='Retain product ID, active release/mode and timestamp with the relevant operational fields. Interpret the result against '+ts[0][0]+' and '+ts[1][0]+'. '+s['restore']+' This text describes the expected evidence, not captured output.')],
 configuration='Configuration intent: '+s['operation']+' Follow the linked release-specific procedure on an exclusively owned disposable target. Keep the original value and affected object/interface scope, not just the proposed command. Stage one change, inspect its diff and stop on partial application or unexpected dependencies. The deliberately introduced scenario is: '+s['fault']+' Rollback must restore the exact baseline: '+s['restore']+' Persist only verified state. Do not remove an entire shared feature, reset a fabric, convert operating mode or broaden tenant policy merely to undo one local edit.',
 production='Operational decision: '+s['operation']+' Assign an owner for the first failing boundary and a separate owner for service acceptance. '+ms[2]+' Include the surviving failure-state envelope, compatibility evidence, independent recovery and rollback time in the change record. A documented source establishes capability only within its stated release/hardware scope. Evidence from a model, a controller and an endpoint must retain those different observer labels.',
 troubleshooting=[[s['fault'],s['restore']],[qs[1][0],qs[1][1]+' '+qs[1][2]],[qs[4][0],qs[4][1]+' '+qs[4][2]],['Status and service disagree','Trace identity → local classification → control/policy → resolved path → original endpoint operation. Capture the first disagreement and restore only the owned scope.']],
 security=security,performance=performance,mistakes=[q[2] for q in qs[:6]],prerequisites=prereq,related=[order[order.index(id)+1]],
 lab=dict(objective=s['operation'],requirements='Browser for the authored incident and bounded model. Optional Cisco observations require an authorized compatible target, matching release documentation and read-only access; no vendor execution is claimed.',topologyKind='shared',topology=[t[0]+' → '+t[1] for t in ts],steps=steps,verification=s['restore']+' Record the original positive and negative service results with observer and timestamp. Distinguish expected behavior from actual captured evidence.',troubleshooting=s['fault']+' '+qs[4][1]+' '+qs[4][2],challenge=qs[5][0]+' Explain a counterexample that would invalidate your first diagnosis.',cleanup='Reset the browser worksheet. On an optional target restore only owned settings to the recorded values, retest the original service and retain sanitized evidence before removing owned fixtures. No host networking, production switch or storage changes are part of the offline exercise.'),
 glossary={t[0]:t[1]+'. '+t[2] for t in ts},sources=[dict(title=sources[k][0],url=sources[k][1],checked='2026-10-09') for k in s['refs']],exams=exams,quick=quick,
 ciscoDC=dict(kind=kind,baseline=s['operation'],fault=s['fault'],restore=s['restore'],scope=scope[kind]),artifacts=[dict(title='Cisco Data Center Batch '+batch+' workbook',path=f'labs/cisco-dc-{batch}-workbook.md')])
 paths={
 's7-g0-t0':['Server NIC → Nexus access port → uplink → destination service','Console/OOB → exact product, mode and release record'],
 's7-g0-t1':['Operator → active feature/configuration → protocol state → hardware forwarding','Verified running intent → deliberate persistence → next-boot intent'],
 's7-g0-t2':['Read-only observer → console or management path → identified target','Timed sample A → original workload → timed sample B'],
 's7-g0-t3':['Ingress port → lookup/policy ASIC → fabric when needed → egress ASIC/queue → destination','Control process → programmed forwarding table'],
 's7-g0-t4':['Many test senders → ingress ports → shared egress queue → one receiver','Unloaded specification → separate loaded latency distribution'],
 's7-g0-t5':['CNA → supported FCoE Ethernet attachment → Nexus storage function → FC fabric/storage','Ethernet carrier → storage login → controlled I/O and integrity'],
 's7-g0-t6':['Tenant A → VDC A → allocated interfaces','Tenant B → VDC B → allocated interfaces','Both VDCs → shared chassis, power and fabric'],
 's7-g0-t7':['NX-OS alternative: device configuration → EVPN control → VXLAN forwarding','ACI alternative: APIC policy → leaf enforcement → endpoint service'],
 'vpc':['Downstream LACP system → member to peer A and member to peer B','Peer A ↔ peer-link port channel ↔ peer B','Peer A ↔ independent keepalive path ↔ peer B','Optional orphan endpoint → one peer; analyze its remote path separately'],
 's7-g2-t0':['Classic Ethernet edge → FabricPath boundary → FabricPath interior → classic edge','Boundary loop prevention and interior topology are separate checks'],
 's7-g2-t1':['Server A → FEX host port → fabric uplink → parent switching','Parent → fabric uplink → FEX host port → server B'],
 's7-g2-t2':['Physical server label → extender serial/FEX ID → host port → parent interface policy','Replacement identity → restored mapping → original server operation'],
 's7-g2-t3':['Site A client → local gateway/policy → inter-site path → Site B service','Separate replication/data-age observation → application recovery verdict'],
 'vxlan':['Host A / local VLAN → ingress VTEP and VNI mapping','Outer VTEP IP → routed spine underlay → remote VTEP IP','Remote VNI mapping → local attachment → Host B'],
 'evpn':['Local endpoint → EVPN originator → BGP distribution → receiving VTEP','Received route → RT import → next-hop resolution → forwarding eligibility'],
 'fabric':['Spine S1 ↔ L1, L2, L3, L4','Spine S2 ↔ L1, L2, L3, L4','Endpoint A → L1 → selected spine → L3 → endpoint B'],
 'aci':['APIC policy intent → leaf policy deployment (management path)','Consumer endpoint → ingress leaf classification → fabric path → provider endpoint','Tenant → VRF → BD; application profile → EPG → BD; contract joins EPG roles']}
 l['lab']['topology']=paths.get(id,paths.get(kind,paths['vxlan'] if kind=='vni' else [t[0]+' → '+t[1] for t in ts]))
 if id=='lab-7':
  l['artifacts'].append(dict(title='Offline two-spine/four-leaf fabric rehearsal',path='labs/cisco-dc-fabric.py'))
  l['lab']['steps'].append('Run python labs/cisco-dc-fabric.py --run. It evaluates synthetic topology, route, MTU and policy records in memory and an owned temporary directory; it sends no traffic and modifies no device.')
  l['commands']=[dict(filename='offline-fabric-rehearsal.txt',platform='Python 3 standard library; actual offline execution, not Cisco execution',code='python labs/cisco-dc-fabric.py --run',explanation='Create only an owned temporary directory; read the baseline plan, withdraw the synthetic App route, restore identical bytes and verify cleanup.',expected='JSON result PASS, restored true and cleaned true, with separate baseline/fault/restore events. This proves only the declared-plan and owned-file behavior.')]
  l['lab']['topology']=['S1 ↔ L1, L2, L3, L4; S2 ↔ L1, L2, L3, L4 (8 underlay links)','Blue Web → L1/L2; Blue App and IP storage → L3/L4','Firewall A → L3; Firewall B → L4; Red Audit → L2','NX-OS: L2 VNI 10100 / RT 65000:10100 for Blue; 10200 / 65000:10200 for Red','ACI alternative: Blue-VRF/Blue-BD → Web, App, Storage EPGs; Red-VRF/Red-BD → Audit EPG']
  plan=runpy.run_path(str(R/'labs/cisco-dc-fabric.py'))['baseline']()
  work+=['## Integrated reference schedule','','The following addresses, rates and roles are invented documentation-range inputs. The offline runner evaluates known-unicast eligibility, not BGP sessions, unknown-unicast flooding, real vPC behavior, storage I/O, firewall HA or application transactions. It does not issue Cisco configuration.','', '| Leaf | VTEP identity | Spine attachments |','|---|---|---|']+[f'| {leaf} | {ip} | S1 and S2; 100 Gb/s each; IP MTU 1600 |' for leaf,ip in plan['leaves'].items()]
  work+=['','| Endpoint | Tenant / EPG | IPv4 | L2 VNI | Leaves |','|---|---|---|---|---|']+[f'| {name} | {e["tenant"]} / {e["epg"]} | {e["ip"]} | {e["vni"]} | {", ".join(e["leaves"])} |' for name,e in plan['endpoints'].items()]
  work+=['','Blue-VNI 10100 imports only RT 65000:10100. Red-VNI 10200 imports only RT 65000:10200. Each synthetic type-2 record carries its endpoint MAC/IP and declared destination leaf set. Dual-leaf attachments are abstract intent: actual supported vPC/EVPN anycast addressing, peer links, keepalive routing and compatibility must be engineered separately. Domain 10 names L1/L2 and domain 20 names L3/L4; no vPC timing or configuration is emulated.','',
  'The baseline Web-to-App flow crosses disjoint leaf pairs. A 1500-byte inner IP packet becomes a 1550-byte outer IPv4 packet in the untagged-inner case, fitting the declared 1600 IP MTU. One-spine loss leaves 100 Gb/s per leaf; 150 Gb/s of inter-leaf demand would no longer fit that envelope. The path predicate does not simulate offered traffic or queueing.','',
  '### Separate ACI mapping','',
  '| Tenant | VRF | BD / subnet | Application profile and EPGs |','|---|---|---|---|','| Blue | Blue-VRF | Blue-BD / 192.0.2.1/24 gateway intent | ThreeTier: Web, App, Storage, Border |','| Red | Red-VRF | Red-BD / 198.51.100.1/24 gateway intent | AuditApp: Audit |','',
  '| Consumer | Provider | One-way service intent | Expected |','|---|---|---|---|','| Blue Web | Blue App | TCP destination 443 | Permitted |','| Blue Web | Blue App | TCP destination 22 | Denied |','| Blue App | Blue Storage | TCP destination 3260 | Permitted |','| Blue Web | Blue Storage | TCP destination 3260 | Denied |','| Red Audit | Blue App | TCP destination 443 | Denied |','',
  'This ACI alternative assumes correctly attached endpoints and the required forwarding context. It evaluates inter-EPG TCP intent only. It does not certify return direction, state tracking, preferred groups, vzAny, shared services, contract inheritance or service graphs. IP storage uses an iSCSI service intent, not a Fibre Channel attachment through the spines. Firewall nodes describe border placement; external routing, state synchronization, asymmetric return paths and gateway HA remain explicit design tasks rather than tested outcomes.','',
  '### Reproduce baseline → fault → exact restore','',
  '1. Run `python labs/cisco-dc-fabric.py` to view help without creating a plan.','2. Run `python labs/cisco-dc-fabric.py --run`. Retain its JSON, baseline hash and three event descriptions.','3. Explain why withdrawing the App route denies known-unicast eligibility while all eight underlay links remain up. Unknown-destination flooding is intentionally excluded.','4. Confirm `restored: true` and `cleaned: true`; restoration writes identical serialized baseline bytes before removing the owned temporary directory.','5. Optionally run `python labs/cisco-dc-fabric.py --run --inject-failure fault`; expected result is INTERRUPTED with restored/cleaned true. An interrupted rehearsal is not normal completion.','6. Compare the separate ACI service table. APIC unavailability alone does not remove already deployed policy in the model. Removing deployed policy does.','7. On a separately authorized disposable Cisco target, replace declarations with actual operational and packet/service evidence using the exact supported release procedures. Do not present this offline JSON as target output.','']
 lessons.append(l)
 work += [f'## {id} — {title}','',s['definition'],'',scope[kind],'','### Evidence and rehearsal','',*['- '+x for x in steps],'','### Guided read-only commands','', '```text',s['command'],'```','','Restoration: '+s['restore'],'']
(R/f'content/batch-{batch}.js').write_text("'use strict';\nwindow.INFRA_BATCHES=window.INFRA_BATCHES||{};window.INFRA_BATCHES['"+batch+"']="+json.dumps(lessons,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
(R/f'labs/cisco-dc-{batch}-workbook.md').write_text('\n'.join(work)+'\n',encoding='utf-8')
if bm['status']!='completed':bm.update(status='in-progress',draftNodeIds=bm['nodeIds'])
bm.update(visualizations='Four-step mechanisms, comparison tables and incident workbenches with scoped calculations.',labs='Guided vendor observation and offline evidence rehearsal; no physical Cisco execution.',interactions=f'{len(lessons)} incident workbenches; {len(lessons)*10} original written exams and {len(lessons)*3} quick checks with self-assessment.')
(R/'content/enrichment.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f'Built {len(lessons)} Batch {batch} drafts; editorial acceptance unchanged.')
